import React, { useState } from 'react';
import './CartItem.css';

const CartItem = ({ item, onCartUpdate }) => {
    const [numbers, setNumbers] = useState(item.numbers || 1);
    const [cover, setCover] = useState(item.cover || "Тверда");

    // Обробка зміни кількості книг
    const handleNumbersChange = (e) => {
        const updatedNumbers = Number(e.target.value);
        setNumbers(updatedNumbers);
        const updatedItem = { ...item, numbers: updatedNumbers, cover };
        updateCartInLocalStorage(updatedItem);
    };

    // Обробка зміни типу обкладинки
    const handleCoverChange = (e) => {
        const updatedCover = e.target.value;
        setCover(updatedCover);
        const updatedItem = { ...item, cover: updatedCover, numbers };
        updateCartInLocalStorage(updatedItem);
    };

    // Оновлення кошика в localStorage
    const updateCartInLocalStorage = (updatedItem) => {
        const updatedCart = JSON.parse(localStorage.getItem('cart')) || [];
        const index = updatedCart.findIndex((cartItem) => cartItem.id === updatedItem.id);
        if (index >= 0) {
            updatedCart[index] = updatedItem;
        } else {
            updatedCart.push(updatedItem);
        }
        localStorage.setItem('cart', JSON.stringify(updatedCart));
        onCartUpdate(updatedCart);
    };

    // Видалення товару з кошика
    const handleRemove = () => {
        const updatedCart = JSON.parse(localStorage.getItem('cart')) || [];
        const filteredCart = updatedCart.filter(cartItem => cartItem.id !== item.id);
        localStorage.setItem('cart', JSON.stringify(filteredCart));
        onCartUpdate(filteredCart);
    };

    const priceMultiplier = cover === "Тверда" ? 1 : cover === "М'яка" ? 0.9 : 1.1;
    const totalPrice = item.price * numbers * priceMultiplier;

    const BACKEND_URL = "http://localhost:5000/static/media";
    const imagePath = `${BACKEND_URL}/${item.image}`;

    return (
        <div className="cart-item">
            <div className="item-image">
                <img src={imagePath} alt={item.title} />
            </div>
            <div className="item-details">
                <h3>{item.title}</h3>
                <p className="item-price">Ціна: {item.price} грн</p>

                <label>
                    Кількість книг:
                    <select value={numbers} onChange={handleNumbersChange}>
                        {Array.from({ length: item.maxNumbers || 10 }, (_, index) => (
                            <option key={index + 1} value={index + 1}>{index + 1}</option>
                        ))}
                    </select>
                </label>

                <label>
                    Обкладинка:
                    <select value={cover} onChange={handleCoverChange}>
                        <option value="Тверда">Тверда</option>
                        <option value="М'яка">М'яка</option>
                        <option value="Суперобкладинка">Суперобкладинка</option>
                    </select>
                </label>
            </div>
            <div className="item-total">
                Загальна вартість: {totalPrice} грн
            </div>

            <button className="remove-button" onClick={handleRemove}>Видалити</button>
        </div>
    );
};

export default CartItem;
